// features/auth.feature: signing out
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in so the request context holds a session cookie (a sign-in test, so credentials are used directly)
  await expectStatus(await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }), 200);
  const before = await request.storageState();
  expect(before.cookies.map((c) => c.name), "signed in with a session cookie").toContain("session");

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie");
  expect(cookie?.value, "logout sends a Set-Cookie for the session").toMatch(/^session=(""|);/);
  expect(cookie?.value.toLowerCase()).toMatch(/max-age=0|expires=thu, 01 jan 1970/);
  const after = await request.storageState();
  expect(after.cookies.map((c) => c.name), "session cookie is gone from the jar").not.toContain("session");
});
